  'Targets stay where you set them.': 'Hedefler senin belirlediğin gibi kalır.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Her sette her tekrarı tamamlarsan ağırlık artar. Üst üste başarısızlık bir deload getirir.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up — double if you double the reps. One failure resets 10 %.': 'İki normal set ve tükenmeye kadar götürülen son bir set. O sette hedefi aşarsan ağırlık artar — tekrarı ikiye katlarsan iki kat artar. Bir başarısızlık %10 geri alır.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Aynı ağırlıkta bir tekrar aralığında yukarı çalış. Her sette aralığın üst sınırına ulaşırsan ağırlık artar, tekrarlar alt sınıra döner.',
  'Hold every set for the full duration and the target goes up.': 'Her seti tam süre boyunca tutarsan hedef artar.',
  'Nothing logged yet — this session sets the baseline.': 'Henüz kayıt yok — bu seans başlangıç noktasını belirler.',
  'Held every set for the full time — target up by {0}s.': 'Her set tam süre tutuldu — hedef {0} sn arttı.',
  'Short {0} sessions in a row — back off to {1}s and build up again.': 'Üst üste {0} seans kısa kaldı — {1} sn’ye in ve yeniden çık.',
  'Last time came up short — same target again.': 'Geçen sefer yetmedi — aynı hedef bir kez daha.',
  'Top of the rep range in every set — {0} {1} more, back to {2} reps.': 'Her sette aralığın üst sınırı — {0} {1} daha, tekrarlar {2}’e dönüyor.',
  'Stalled {0} sessions — deload to {1} {2}.': '{0} seanstır takıldın — {1} {2} ağırlığa deload.',
  'Same weight — aim for {0} reps this time.': 'Aynı ağırlık — bu sefer {0} tekrarı hedefle.',
  'Last set hit {0} reps — twice the target, so take a double jump of {1} {2}.': 'Son set {0} tekrar — hedefin iki katı, bu yüzden {1} {2} çift artış.',
  'Every rep last time — {0} {1} more.': 'Geçen sefer bütün tekrarlar tamam — {0} {1} daha.',
  'Missed reps {0} sessions running — reset to {1} {2} and work back up.': 'Üst üste {0} seans tekrarlar eksik — {1} {2} ağırlığa dön ve yeniden çık.',
  'Missed reps — reset to {0} {1} and work back up.': 'Tekrarlar eksik kaldı — {0} {1} ağırlığa dön ve yeniden çık.',
  'Missed reps last time — same weight again ({0} of {1} to go).': 'Geçen sefer tekrarlar eksikti — aynı ağırlık bir kez daha ({1} denemeden {0} kaldı).',
  'Bodyweight — every rep last time, so go for {0} this time.': 'Vücut ağırlığı — geçen sefer bütün tekrarlar tamamdı, bu sefer {0} hedefle.',
  'Bodyweight — same target again until every set is clean.': 'Vücut ağırlığı — her set temiz çıkana kadar aynı hedef.',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them — switch on Effort per set in Settings to see it.': '{0} set beraberinde bir {1} getiriyor — görmek için Ayarlar’da «Set başına efor» seçeneğini aç.',
  '{0} sets bring an {1} with them.': '{0} set beraberinde bir {1} getiriyor.',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': 'Set başına zorluk',
  'What are RIR and RPE?': 'RIR ve RPE nedir?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': 'Bir setin ne kadar zor geçtiği, ağırlık ve tekrarların yanında. Aynı değerlendirme için iki ölçek, ters uçlardan sayılıyor.',
  'How it felt': 'Nasıl hissettirdi',
  'Nothing left — went to failure': 'Hiç kalmadı — tükenmeye kadar',
  'One more rep in the tank': 'Bir tekrar daha vardı',
  'Two more reps': 'İki tekrar daha vardı',
  'Three more reps': 'Üç tekrar daha vardı',
  'Easy — warm-up territory': 'Kolay — ısınma bölgesi',
  'RIR counts the reps you left; RPE reads the same effort off a 10-point scale — so RPE ≈ 10 − RIR. Pick the one you already think in.': 'RIR yedekte bıraktığın tekrarları sayar; RPE aynı eforu 10’luk ölçekte okur — yani RPE ≈ 10 − RIR. Zaten hangisiyle düşünüyorsan onu seç.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value — progression and estimated 1RM are unaffected.': 'Vurgulanan satır, çalışma setlerinin çoğunun denk geldiği yerdir. Daha önce kaydettiğin setler kendi ölçeğini korur ve bu değeri başka hiçbir şey okumaz — ilerleme ve tahmini 1RM etkilenmez.',
