  'An AI coach that can build your plan and adjust it from what you log. Off until you turn it on.': 'Planını oluşturan ve kaydettiklerine göre ayarlayan bir yapay zekâ koçu. Sen açana kadar kapalı.',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': 'Planını tasarlayan ve kaydettiklerine göre ayarlayan bir yapay zekâ koçu. Bu sunucuda çalışır, onayın olmadan hiçbir şeyi değiştirmez ve sen açana kadar kapalıdır.',
  'Any pending suggestion is discarded and scheduled reviews stop. Your Coach history stays, and you can turn it back on anytime.': 'Bekleyen öneriler silinir ve planlanmış değerlendirmeler durur. Geçmişin kalır, istediğin zaman yeniden açabilirsin.',
