  'No exercises yet.': 'Henüz egzersiz yok.',
  'Full body A': 'Tüm vücut A',
  'Full body B': 'Tüm vücut B',
  'Coach plan': 'Koç planı',
  'Vertical pressing.': 'Dikey itiş.',
  'Same pattern, higher reps than day A.': 'Aynı kalıp, A gününden daha çok tekrar.',
  'Direct arm work, since you asked for it.': 'Doğrudan kol çalışması, istediğin için.',
  'Horizontal pressing, the other half of the session.': 'Yatay itiş, seansın diğer yarısı.',
  'A pull for every press, so the shoulders stay balanced.': 'Her itişe bir çekiş, omuzlar dengede kalsın diye.',
  'The main lower-body driver — where most of the strength comes from.': 'Alt vücudun ana hareketi — gücün çoğu buradan gelir.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Önce iki büyük kalıp, alt vücut ve itiş, henüz zindeyken.',
  'The same patterns, different variations — enough overlap to progress, enough difference to stay fresh.': 'Aynı kalıplar, farklı varyasyonlar — ilerlemeye yetecek kadar örtüşme, zinde kalmaya yetecek kadar farklılık.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Belirttiğin ekipmana göre kurulmuş, haftada üç seanslık iki günlük bir rotasyon. Önce bileşik hareketler, her itişe bir çekiş ve hiçbir şeyin iki hafta çalışılmadan kalmayacağı kadar örtüşme.',
  'Based on the training already in this demo profile.': 'Bu demo profilindeki antrenmanlara dayanarak.',
  'No training history yet — starting conservatively.': 'Henüz antrenman geçmişi yok — temkinli başlıyoruz.',
  'The Coach is already thinking about your training.': 'Koç zaten antrenmanın üzerinde düşünüyor.',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'İstediğin gibi düzeltildi. Sorgulamadığın her şey olduğu gibi duruyor.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Bu hareketteki her üst set üç seans boyunca RPE 9,5 veya üzerindeydi ve ağırlık değişmedi. Hareketi dört haftalığına değiştirmek, aynısında ısrar etmekten genelde daha hızlı aşar bu durağanlığı.',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Seanslar yaklaşık on beş dakika uzuyor. Bir set eksik olmasından en az etkilenecek yardımcı hareket bu.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Bu seansı üç haftadır cumartesiye taşıyorsun. Sürekli değiştirmektense planın bunu söylemesi daha iyi.',
  'Three things worth changing, and one worth knowing about. Everything else is working — the squat and the pulls are both progressing on schedule.': 'Değiştirmeye değer üç şey ve bilmeye değer bir şey. Geri kalan her şey işliyor — squat ve çekişler planlandığı gibi ilerliyor.',
  'Body weight has been flat for four weeks while the goal is to gain. That is a kitchen problem rather than a training one — the plan is not what is holding it back.': 'Hedef kilo almakken vücut ağırlığı dört haftadır sabit. Bu antrenmandan çok mutfak sorunu — seni geri tutan plan değil.',
  // 2.2
  'Physical activity': 'Fiziksel aktivite',
  'Counts every step you take.': 'Attığın her adımı sayar.',
  'Live step counter on the lock screen, alerts every 1,000 steps.': 'Kilit ekranında canlı adım sayacı, her 1.000 adımda bildirim.',
  'Run in the background': 'Arka planda çalış',
  'Keeps counting with the app closed and the screen off — no stopping.': 'Uygulama kapalı ve ekran kapalıyken de saymaya devam eder — durmadan.',
  'Start after restart': 'Yeniden başlatmadan sonra başla',
  'Switches itself back on when the phone is turned off and on again.': 'Telefon kapatılıp açıldığında kendiliğinden yeniden açılır.',
  'Step counter on': 'Adım sayar açık',
  'Starts counting right away.': 'Hemen saymaya başlar.',
  'Counts while this page is open.': 'Bu sayfa açık olduğu sürece sayar.',
  'Welcome to MAHDI-JYM': 'MAHDI-JYM\'e hoş geldin',
  'To count your steps all day — in the background, with the screen locked and after a restart — MAHDI-JYM needs a few permissions.': 'Adımlarını gün boyu — arka planda, ekran kilitliyken ve yeniden başlatmadan sonra — sayabilmek için MAHDI-JYM\'in birkaç izne ihtiyacı var.',
  'To count your steps and notify you, MAHDI-JYM needs a few permissions.': 'Adımlarını saymak ve sana bildirim göndermek için MAHDI-JYM\'in birkaç izne ihtiyacı var.',
  'By tapping Agree you use MAHDI-JYM at your own responsibility. It is not a medical device: steps, distance, calories and speed are estimates. Check with a doctor before starting a training program. Your data stays on your device.': 'Kabul et\'e dokunarak MAHDI-JYM\'i kendi sorumluluğunda kullanırsın. Bu bir tıbbi cihaz değildir: adımlar, mesafe, kalori ve hız tahminidir. Bir antrenman programına başlamadan önce doktoruna danış. Verilerin cihazında kalır.',
  'Agree & allow': 'Kabul et ve izin ver',
  'Setting up…': 'Ayarlanıyor…',
  'Answer “Allow” on each screen that appears.': 'Çıkan her ekranda “İzin ver”i seç.',
  'One more step': 'Bir adım daha',
  '{0} phones also stop apps in the background unless you allow them. Turn on Autostart (or “No restrictions”) for MAHDI-JYM.': '{0} telefonlar, izin vermezsen uygulamaları arka planda da durdurur. MAHDI-JYM için Otomatik başlatmayı (veya “Kısıtlama yok”u) aç.',
  'Open settings': 'Ayarları aç',
  'All set': 'Her şey hazır',
  'MAHDI-JYM now counts your steps in the background, also with the screen off and after a restart. You can change this any time under Walking.': 'MAHDI-JYM artık adımlarını arka planda, ekran kapalıyken ve yeniden başlatmadan sonra da sayıyor. Bunu istediğin zaman Yürüyüş bölümünden değiştirebilirsin.',
  'Browsers can only count while the page is open. For counting in the background, with the screen off and after a restart, install the Android app.': 'Tarayıcılar yalnızca sayfa açıkken sayabilir. Arka planda, ekran kapalıyken ve yeniden başlatmadan sonra saymak için Android uygulamasını yükle.',
  'Download the Android app': 'Android uygulamasını indir',
