  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': 'Tekrar hoş geldin — verilerin Google hesabından geri yüklendi',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': 'Google Drive bu uygulama sürümü için henüz ayarlanmadı — yine de verilerin Android Yedekleme ile Google hesabına kaydediliyor.',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'Google hesabına gizli olarak kaydedilir — yalnızca MAHDI-JYM okuyabilir. İstediğin zaman Ayarlar’dan çıkış yapabilirsin.',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': 'Her şey Android Yedekleme ile Google hesabına otomatik kaydedilir ve MAHDI-JYM’yi yeniden yüklediğinde geri gelir.',
  'Now saved to Google Drive': 'Artık Google Drive’a kaydediliyor',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': 'Verilerin bu telefonda kalır. Değişiklikler artık Google hesabına kaydedilmez.',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': 'Bu telefonda zaten olan bir Google hesabıyla giriş yap — şifresiz. Sonra her şey o hesaba otomatik kaydedilir.',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': 'Antrenmanlar, plan, adımlar, su, vücut ağırlığı ve ayarlar Android Yedekleme ile Google hesabına kaydedilir. Android bunları arka planda, genellikle birkaç saat içinde yükler ve MAHDI-JYM’yi yeniden ya da yeni bir telefona yüklediğinde geri getirir. İlerleme fotoğrafları bu telefonda kalır.',
