  "That needs a one-time setup in Google Cloud by the app’s owner. Until then everything is saved through Android Backup — nothing is lost.": "Bunun için uygulama sahibinin Google Cloud’da tek seferlik bir kurulum yapması gerekir. O zamana kadar her şey Android Backup ile kaydedilir — hiçbir şey kaybolmaz.",
