  "Automatic versions": "Otomatik sürümler",
  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "Günde bir kez, bir şey değiştiyse, tam bir kopya bu telefonda ve Google Drive’da saklanır. En yeniler tutulur, eskiler silinir.",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "Günde bir kez, bir şey değiştiyse, tam bir kopya bu telefonda saklanır. En yeniler tutulur, eskiler silinir.",
