  "No versions in Drive yet.": "Drive’da henüz sürüm yok.",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "Bir sürüm tam bir kopyadır: antrenmanlar, plan, rutinler, adımlar, su, vücut ağırlığı, sağlık günlüğü ve ayarlar. İlerleme fotoğrafları yerinde kalır. Her yerde saklayabileceğin bir kopya için Ayarlar’daki Dışa aktar’ı kullan.",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "Google hesabınla console.cloud.google.com’u aç ve bir proje oluştur (herhangi bir ad).",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services → Library → “Google Drive API” ara → Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen → External → uygulama adını ve e-postanı gir → …/auth/drive.appdata kapsamını ekle → kendi hesabını test kullanıcısı olarak ekle.",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials → Create credentials → OAuth client ID → Android → aşağıdaki paket adını ve SHA-1’i yapıştır.",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "Yaklaşık 5 dakika bekle, sonra buraya dön ve Tekrar dene’ye dokun. Uygulamanın kendisinde bir şey değişmez.",
  "Switch on Google Drive": "Google Drive’ı aç",
