  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "Google Cloud’da: API’ler ve Hizmetler → Kitaplık → Google Drive API → Etkinleştir. Birkaç dakika sonra tekrar test edin.",
