  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "Google Cloud’da tam olarak burada görünen paket adı ve SHA-1 ile bir Android OAuth istemcisi oluşturun. Yaklaşık 5 dakika bekleyip tekrar test edin.",
  "Access to Google Drive wasn’t allowed": "Google Drive erişimine izin verilmedi",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "“Google Drive’ı test et”e dokunun ve İzin ver’i seçin. Uygulama test aşamasındayken hesabınız OAuth izin ekranında test kullanıcısı olarak ekli olmalı.",
