  "Save to your Google Drive too": "Google Drive'ına da kaydet",
  "Your data is already saved to your Google account through Android Backup. Add a file in your own Google Drive that you can see, and that is updated with every change — no setup.": "Verilerin zaten Android Yedekleme ile Google hesabına kaydediliyor. Kendi Google Drive'ında görebileceğin ve her değişiklikte güncellenen bir dosya ekle — kurulum gerekmez.",
  "The Google Drive app isn’t installed — install it to see Drive in the window.": "Google Drive uygulaması yüklü değil — Drive'ın pencerede görünmesi için yükle.",
