  "Your data stays on this phone and in your Google Drive. Changes are no longer saved to your Google account or to the Drive file.": "Verilerin bu telefonda ve Google Drive'ında kalır. Değişiklikler artık Google hesabına veya Drive dosyasına kaydedilmez.",
  "Every change is written to your file a moment after you make it. Sign in with Google as well to also keep a copy through Android Backup.": "Her değişiklik birkaç saniye sonra dosyana yazılır. Android Yedekleme ile bir kopya da tutmak için Google ile de giriş yap.",
