  "Phone": "Telefon",
  "In the phone settings the notifications are grouped: steps & activity, water, schedule & meals, workouts, health.": "Telefon ayarlarında bildirimler gruplanır: adımlar ve aktivite, su, program ve öğünler, antrenmanlar, sağlık.",
