  "Send a test notification": "Test bildirimi gönder",
  "School, meals, drinks, work": "Okul, öğün, içecek, iş",
  "Food & drinks": "Yiyecek ve içecek",
  "Activity": "Aktivite",
  "Body & health": "Vücut ve sağlık",
  "Reports & reminders": "Raporlar ve hatırlatıcılar",
  "Reminders that show everything": "Her şeyi gösteren hatırlatıcılar",
  "Arrange everything yourself — school, meals, drinks, work, prayer — on the days you choose, with an end time and your own notes.": "Her şeyi kendin düzenle — okul, öğünler, içecekler, iş, namaz — seçtiğin günlerde, bitiş saati ve kendi notlarınla.",
  "School Sunday to Thursday, 7:30 to 12:40, then lunch, rest, homework, work, drinks and dinner — and a calmer weekend.": "Pazardan perşembeye okul, 7:30–12:40, sonra öğle yemeği, dinlenme, ödev, iş, içecekler ve akşam yemeği — ve daha sakin bir hafta sonu.",
  "Each reminder shows the time, your notes and the food and drinks you chose with their calories — with Done ✓ and In 10 min.": "Her hatırlatıcı saati, notlarını ve seçtiğin yiyecek ve içecekleri kalorileriyle gösterir — “Tamam ✓” ve “10 dk sonra” ile.",
  "Colas, lemon-lime, fruit sodas, malt and energy drinks and homemade mojitos — in cans, bottles and glasses of every size, with sugar in teaspoons.": "Kolalar, limonlu gazozlar, meyveli gazozlar, malt ve enerji içecekleri, ev yapımı mojitolar — her boy kutu, şişe ve bardakta, şeker çay kaşığı olarak.",
  "Pistachios, almonds, walnuts, cashews, the seeds you crack and kerzat — raw, roasted or salted, by the handful, with what each is good for.": "Fıstık, badem, ceviz, kaju, çitlenen çekirdekler ve çerez — çiğ, kavrulmuş ya da tuzlu, avuç avuç, her birinin faydasıyla.",
  "All notifications in one place": "Tüm bildirimler tek yerde",
  "Which reminders are on, what still rings today, and the phone’s notification settings grouped by kind.": "Hangi hatırlatıcıların açık olduğu, bugün daha neyin çalacağı ve türe göre gruplanmış telefon bildirim ayarları.",
  "Smoother everywhere": "Her yerde daha akıcı",
  "Tidier tools, smoother animations and many small fixes — drinks are now logged to the right meal.": "Daha düzenli araçlar, daha akıcı animasyonlar ve birçok küçük düzeltme — içecekler artık doğru öğüne kaydediliyor.",
