  "Values are typical per 100 ml — recipes differ from country to country, so check the label. Brand names belong to their owners.": "Değerler 100 ml başına tipiktir — tarifler ülkeden ülkeye değişir, etiketi kontrol et. Marka adları sahiplerine aittir.",
  "Values per 100 g of the edible part, rounded. Roasting removes water, so roasted nuts have a few more calories per gram.": "Değerler yenilebilir kısmın 100 g'ı içindir, yuvarlanmıştır. Kavurma suyu azaltır; bu yüzden kavrulmuş kuruyemişin gram başına kalorisi biraz daha fazladır.",
