  "Regular colas are high in sugar and have some caffeine. The zero versions have no calories.": "Normal kolalar çok şekerlidir ve biraz kafein içerir. Zero versiyonların kalorisi yoktur.",
  "Lemon & lime": "Limon ve misket limonu",
