  "Fruit sodas": "Meyveli gazozlar",
  "Coloured and sweet, usually with no real fruit. Sparkling water with fresh juice is a lighter choice.": "Renkli ve tatlı, çoğu zaman gerçek meyve yok. Taze meyve sulu maden suyu daha hafif bir seçim.",
  "Soda & sparkling water": "Soda ve maden suyu",
  "Soda and sparkling water have no calories. Tonic water and ginger ale are sweetened.": "Soda ve maden suyunun kalorisi yok. Tonik ve zencefilli gazoz şekerlidir.",
  "Malt drinks 0.0%": "Malt içecekleri %0,0",
  "Malt drinks have no alcohol. The flavoured ones are as sweet as soft drinks; the classic is lighter.": "Malt içeceklerinde alkol yoktur. Aromalılar gazoz kadar tatlıdır; klasik olanı daha hafiftir.",
  "Energy drinks": "Enerji içecekleri",
  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "Çok kafein ve şeker. Çocuklar, hamileler ve kafeine hassas olanlar için değil — günde en fazla bir kutu.",
  "Homemade sodas": "Ev yapımı gazozlar",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "Evde soda, taze limon ve naneyle yapılır — tatlılığına sen karar verirsin. Değerler biraz şeker varsayar.",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "Yüksek kafein — çocuklar, hamileler ve kafeine hassas olanlar için değil. Asla alkolle karıştırma, sıcakta ağır egzersiz sırasında da içme.",
