  "A milky morning tea — breakfast in many Iraqi homes.": "Sabahın sütlü çayı — birçok Irak evinin kahvaltısı.",
  "Tea with a squeeze of lemon — light after a heavy meal.": "Birkaç damla limonlu çay — ağır bir yemekten sonra hafif gelir.",
  "Tea with fresh mint from the garden, after lunch.": "Bahçeden taze naneli çay, öğle yemeğinden sonra.",
  "Hot cocoa on cold Baghdad winter evenings.": "Bağdat’ın soğuk kış akşamlarında sıcak kakao.",
  "Warm milk sweetened with date syrup — a winter comfort.": "Hurma pekmeziyle tatlandırılmış ılık süt — kışın içini ısıtır.",
  "Small and strong, sipped slowly after a meal or with guests.": "Küçük ve sert; yemekten sonra ya da misafirle yavaş yavaş içilir.",
  "The quick coffee of students and late-night studying.": "Öğrencilerin ve gece ders çalışmanın hızlı kahvesi.",
  "Squeezed fresh at home on long, hot summer afternoons.": "Uzun ve sıcak yaz öğleden sonralarında evde taze sıkılır.",
  "Sweet and sour — a Ramadan favourite poured cold at iftar.": "Ekşi ve tatlı — iftarda soğuk içilen bir Ramazan sevgilisi.",
  "Oranges from the orchards of Diyala, squeezed at the juice shop.": "Diyala bahçelerinin portakalları, meyve suyu dükkânında sıkılır.",
  "Freshly pressed carrots — sold in every Iraqi juice shop.": "Taze sıkılmış havuç — her Irak meyve suyu dükkânında.",
  "Fresh apples blended at the juice shop.": "Meyve suyu dükkânında çekilmiş taze elma.",
  "Made from the sweet grapes of Iraqi summers.": "Irak yazlarının tatlı üzümlerinden.",
  "Thick mango juice, a favourite at Basra’s juice stands.": "Koyu mango suyu, Basra’daki meyve suyu tezgâhlarının gözdesi.",
  "The juice shop’s best seller — banana and cold milk.": "Meyve suyu dükkânının en çok satanı — muz ve soğuk süt.",
  "A pink favourite when strawberries are in season.": "Çilek mevsiminin pembe gözdesi.",
  "Layers of fruit, milk and nuts — the famous Iraqi juice-shop cocktail.": "Kat kat meyve, süt ve kuruyemiş — Irak meyve suyu dükkânlarının ünlü kokteyli.",
  "Instant coffee": "Hazır kahve",
